catalog = FileAttachment("data/final_results/catalog.json").json()
movies = catalog.movies || []

// Helper: Count occurrences
function countBy(array, key) {
  const counts = {};
  for (const item of array) {
    const value = item[key];
    if (value) {
      counts[value] = (counts[value] || 0) + 1;
    }
  }
  return Object.entries(counts).sort((a, b) =&gt; b[1] - a[1]);
}

// Helper: Count array values (for genres)
function countArrayValues(array, key) {
  const counts = {};
  for (const item of array) {
    const values = item[key] || [];
    for (const value of values) {
      if (value) {
        counts[value] = (counts[value] || 0) + 1;
      }
    }
  }
  return Object.entries(counts).sort((a, b) =&gt; b[1] - a[1]);
}

// Stats
totalCount = movies.length
enrichedCount = movies.filter(m =&gt; m.enriched).length
withPoster = movies.filter(m =&gt; m.poster && m.poster !== "https://i.imgur.com/Ngnm5v6.png").length
withDirector = movies.filter(m =&gt; m.director).length
withYear = movies.filter(m =&gt; m.year).length



































































