})


























directorData = movies.flatMap(m =&gt; {
  const directors = (m.director || "").split(",").map(d =&gt; d.trim()).filter(Boolean);
  return directors.map(d =&gt; ({director: d}));
});

directorCounts = countBy(directorData, "director").slice(0, 15)

Plot.plot({
