catalog = FileAttachment("data/final_results/catalog.json").json()

// Extract movies array
movies = catalog.movies || []

// Get unique genres for filter (flatten and dedupe)
genres = [...new Set(movies.flatMap(m =&gt; m.genre || []))].filter(Boolean).sort()

// Stats
enrichedCount = movies.filter(m =&gt; m.enriched).length
totalCount = movies.length
enrichmentRate = Math.round(enrichedCount / totalCount * 100)














































// Display stats cards
html`&lt;div class="stats-container"&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-value"&gt;${totalCount}&lt;/div&gt;
    &lt;div class="stat-label"&gt;Total Películas&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-value"&gt;${enrichedCount}&lt;/div&gt;
    &lt;div class="stat-label"&gt;Con Datos OMDB&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-value"&gt;${enrichmentRate}%&lt;/div&gt;
    &lt;div class="stat-label"&gt;Enriquecidas&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-value"&gt;${genres.length}&lt;/div&gt;
    &lt;div class="stat-label"&gt;Géneros&lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;`










viewof searchQuery = Inputs.text({
  label: "Buscar",
  placeholder: "Título, director, género, país, año...",
  value: ""
})

// Genre filter
viewof selectedGenre = Inputs.select(
  ["Todos", ...genres],
  {label: "Género", value: "Todos"}
)

// Director filter (dynamic based on data)
directors = [...new Set(movies.map(m =&gt; m.director).filter(Boolean))].sort()
viewof selectedDirector = Inputs.select(
  ["Todos", ...directors.slice(0, 100)],
  {label: "Director", value: "Todos"}
)

// Enrichment filter
viewof showEnrichedOnly = Inputs.toggle({label: "Solo con datos OMDB", value: false})

// Reset button
viewof resetFilters = Inputs.button("Restablecer filtros", {value: null})

// Reactive: Reset filters when button clicked
resetTrigger = {
  resetFilters;
  return Date.now();
}

// Filtered movies (reactive)
filteredMovies = {
  resetTrigger;
  let result = movies;

  // Enriched-only filter
  if (showEnrichedOnly) {
    result = result.filter(m =&gt; m.enriched);
  }

  // Genre filter
  if (selectedGenre !== "Todos") {
    result = result.filter(m =&gt; (m.genre || []).includes(selectedGenre));
  }

  // Director filter
  if (selectedDirector !== "Todos") {
    result = result.filter(m =&gt; m.director === selectedDirector);
  }

  // Search query filter
  if (searchQuery) {
    const query = searchQuery.toLowerCase();
    result = result.filter(m =&gt;
      (m.search_text || "").includes(query) ||
      (m.title || "").toLowerCase().includes(query) ||
      (m.matched_title || "").toLowerCase().includes(query) ||
      (m.director || "").toLowerCase().includes(query) ||
      (m.country || "").toLowerCase().includes(query) ||
      String(m.catalogue_id || "").includes(query)
    );
  }

  return result;
}





























































movieGrid = {
  if (filteredMovies.length === 0) {
    return html`&lt;div class="no-results"&gt;No se encontraron películas con los filtros seleccionados.&lt;/div&gt;`;
  }

  const grid = html`&lt;div class="movie-grid"&gt;&lt;/div&gt;`;

  for (const movie of filteredMovies) {
    const poster = movie.poster || "https://i.imgur.com/Ngnm5v6.png";
    const imdbUrl = movie.imdb_id ? `https://www.imdb.com/title/${movie.imdb_id}` : null;
    const idLabel = movie.catalogue_id != null ? `#${movie.catalogue_id}` : "";

    const card = html`
      &lt;div class="movie-card ${movie.enriched ? '' : 'unenriched'}"&gt;
        &lt;div class="movie-poster-container"&gt;
          &lt;img class="movie-poster" src="${poster}" alt="${movie.title}" loading="lazy"
               onerror="this.src='https://i.imgur.com/Ngnm5v6.png'"&gt;
          ${movie.imdb_rating ? html`&lt;div class="rating-badge"&gt;⭐ ${movie.imdb_rating}&lt;/div&gt;` : null}
        &lt;/div&gt;
        &lt;div class="movie-info"&gt;
          &lt;div class="card-header-row"&gt;
            ${idLabel ? html`&lt;span class="catalogue-id-badge"&gt;${idLabel}&lt;/span&gt;` : null}
            ${!movie.enriched ? html`&lt;span class="unenriched-badge"&gt;Sin datos&lt;/span&gt;` : null}
          &lt;/div&gt;
          &lt;h3 class="movie-title" title="${movie.title}"&gt;${movie.title}&lt;/h3&gt;
          ${movie.matched_title && movie.matched_title !== movie.title ?
            html`&lt;div class="original-title"&gt;${movie.matched_title}&lt;/div&gt;` : null}
          ${movie.year ? html`&lt;div class="movie-year"&gt;📅 ${movie.year}&lt;/div&gt;` : null}
          ${movie.director ? html`&lt;div class="movie-director"&gt;🎬 ${movie.director}&lt;/div&gt;` : null}
          ${movie.genre?.length ? html`&lt;div class="movie-genres"&gt;${movie.genre.slice(0, 3).map(g =&gt;
            html`&lt;span class="genre-tag"&gt;${g}&lt;/span&gt;`
          )}&lt;/div&gt;` : null}
          ${movie.country ? html`&lt;div class="movie-country"&gt;🌍 ${movie.country}&lt;/div&gt;` : null}
          ${movie.plot ? html`&lt;div class="movie-plot"&gt;${movie.plot.substring(0, 120)}${movie.plot.length &gt; 120 ? "..." : ""}&lt;/div&gt;` : null}
          ${imdbUrl ? html`&lt;a href="${imdbUrl}" target="_blank" class="imdb-link"&gt;Ver en IMDb →&lt;/a&gt;` : null}
        &lt;/div&gt;
      &lt;/div&gt;
    `;
    grid.appendChild(card);
  }

  return grid;
}

