        &lt;div class="movie-poster-container"&gt;
          &lt;img class="movie-poster" src="${poster}" alt="${movie.title}" loading="lazy"
               onerror="this.src='https://i.imgur.com/Ngnm5v6.png'"&gt;
          ${movie.imdb_rating ? html`&lt;div class="rating-badge"&gt;⭐ ${movie.imdb_rating}&lt;/div&gt;` : null}
        &lt;/div&gt;
        &lt;div class="movie-info"&gt;
          &lt;div class="card-header-row"&gt;
            ${idLabel ? html`&lt;span class="catalogue-id-badge"&gt;${idLabel}&lt;/span&gt;` : null}
            ${!movie.enriched ? html`&lt;span class="unenriched-badge"&gt;Sin datos&lt;/span&gt;` : null}
          &lt;/div&gt;
          &lt;h3 class="movie-title" title="${movie.title}"&gt;${movie.title}&lt;/h3&gt;
          ${movie.matched_title && movie.matched_title !== movie.title ?
            html`&lt;div class="original-title"&gt;${movie.matched_title}&lt;/div&gt;` : null}
          ${movie.year ? html`&lt;div class="movie-year"&gt;📅 ${movie.year}&lt;/div&gt;` : null}
          ${movie.director ? html`&lt;div class="movie-director"&gt;🎬 ${movie.director}&lt;/div&gt;` : null}
          ${movie.genre?.length ? html`&lt;div class="movie-genres"&gt;${movie.genre.slice(0, 3).map(g =&gt;
            html`&lt;span class="genre-tag"&gt;${g}&lt;/span&gt;`
          )}&lt;/div&gt;` : null}
          ${movie.country ? html`&lt;div class="movie-country"&gt;🌍 ${movie.country}&lt;/div&gt;` : null}
          ${movie.plot ? html`&lt;div class="movie-plot"&gt;${movie.plot.substring(0, 120)}${movie.plot.length &gt; 120 ? "..." : ""}&lt;/div&gt;` : null}
          ${imdbUrl ? html`&lt;a href="${imdbUrl}" target="_blank" class="imdb-link"&gt;Ver en IMDb →&lt;/a&gt;` : null}
        &lt;/div&gt;
      &lt;/div&gt;
    `;
    grid.appendChild(card);
  }

  return grid;
}

